const t=document.querySelector(".mobile-toggle"),o=document.querySelector(".nav-menu");t?.addEventListener("click",()=>{const e=t.getAttribute("aria-expanded")==="true";t.setAttribute("aria-expanded",String(!e)),o?.classList.toggle("open"),document.body.style.overflow=e?"":"hidden"});o?.querySelectorAll("a").forEach(e=>{e.addEventListener("click",()=>{t?.setAttribute("aria-expanded","false"),o.classList.remove("open"),document.body.style.overflow=""})});
